yakit.AutoInitYakit()

# 全局路径收集器
globalPaths = container.NewSet()
patternPaths = container.NewSet()  # 存储归纳后的模式 
webpackFiles = container.NewSet()
sourceMapFiles = container.NewSet()
# 添加Host白名单参数
whiteHosts = cli.Text("whiteHosts", cli.setHelp("按行分隔会与数据包中的Host做关键字匹配"), cli.setVerboseName("Host白名单"),cli.setRequired(true))
cli.check()

# 解析白名单Host列表
whiteHostList = []
if whiteHosts != "" {
    whiteHostList = str.ParseStringToLines(whiteHosts)
}


isHostAllowed = func(host) {
    if len(whiteHostList) == 0 {
        return true
    }
    

    for whiteHost in whiteHostList {
        whiteHost = str.TrimSpace(whiteHost)
        if whiteHost == "" {
            continue
        }
        

        if str.Contains(whiteHost, "*") {
            pattern = str.ReplaceAll(whiteHost, "*", ".*")
            if re.Match("^" + pattern + "$", host) {
                return true
            }
        } else {
            if str.Contains(host, whiteHost) {
                return true
            }
        }
    }
    

    return false
}
# 静态文件后缀列表
staticFileSuffixes = [".css", ".jpg", ".jpeg", ".png", ".gif", ".wmv", ".a3c", ".ace", ".aif", ".aifc", ".aiff", ".arj", ".asf", ".asx", ".attach", ".au", ".avi", ".bin", ".bmp", ".cab", ".cache", ".class", ".djv", ".djvu", ".dwg", ".es", ".esl", ".exe", ".fif", ".fvi", ".gz", ".hqx", ".ice", ".ico", ".ief", ".ifs", ".iso", ".jar", ".jpe", ".kar", ".mdb", ".mid", ".midi", ".mov", ".movie", ".mp", ".mp2", ".mp3", ".mp4", ".mpeg", ".mpeg2", ".mpg", ".mpg2", ".mpga", ".msi", ".pac", ".pdf", ".ppt", ".psd", ".qt", ".ra", ".ram", ".rar", ".rm", ".rpm", ".snd", ".svf", ".tar", ".tgz", ".tif", ".tiff", ".tpl", ".ttf", ".uff", ".wav", ".wma", ".zip", ".woff", ".woff2", ".apk"]

# 检查是否为静态文件
isStaticFile = func(path) {
    if path == nil || path == "" {
        return false
    }
    

    ext = file.GetExt(path)
    if ext == "" {
        return false
    }
    

    ext = str.ToLower(ext)

    for suffix in staticFileSuffixes {
        if ext == suffix {
            return true
        }
    }
      # 过滤包含图片处理参数的路径  
    if str.Contains(path, "@!") || str.Contains(path, "?x-oss-") {  
        return true  
    }  

    return false
}

# 使用set实现list去重并且排序返回
deduplicateStrings = func(list) {
    tempMap = container.NewSet()
    for i in list {
        tempMap.Add(str.TrimSpace(i))
    }
    

    arr = tempMap.ToSlice().StringSlice()
    arr.Sort()
    return arr
}

# 传入一个json，递归获取json key，返回json key列表
getJsonKey = func(jsn) {
    parameter = []

    try {
        for key, value = range jsn {
            if key != "" && typeof(key) != int {
                parameter.Append(str.TrimSpace(key))
            }
            

            if typeof(value) != string && typeof(value) != int && typeof(value) != float && typeof(value) != bool && value != nil {
                parameter += getJsonKey(value)
            }
        }
    } catch err {
        println(err)
    }


    return deduplicateStrings(parameter)
}

// isMostlyPrintable 判断数据是否大部分为可打印字符。用于去除二进制流请求数据包。
// 若数据为空，默认返回 true（认为是"可打印"的空数据）。
isMostlyPrintable = func(bodyData) {
    if len(bodyData) == 0 {
        return true// 空数据视为可打印  
    }
    

    printable := 0
    for i := 0; i < len(bodyData); i++ {
        if bodyData[i] >= 32 && bodyData[i] <= 126 {
            printable++
        }
    }
    

    return float(printable) / float(len(bodyData)) > 0.9
}

// 获取请求的请求参数
parseQueryKeys = func(flow) {
    keys = []

    params = poc.GetAllHTTPPacketQueryParamsFull(flow.GetRequest())
    for i in params.Keys() {
        keys.Append(str.TrimSpace(i))
    }
    

    if flow.Method == "POST" {
        req, err = poc.ParseBytesToHTTPRequest(flow.GetRequest())
        if err != nil {
            return deduplicateStrings(keys)
        }
        

        if !isMostlyPrintable(poc.GetHTTPPacketBody(flow.GetRequest())) {
            return deduplicateStrings(keys)
        }
        

        if str.Contains(string(req.Header["Content-Type"]), "application/x-www-form-urlencoded") {
            paramsPost = poc.GetAllHTTPPacketPostParamsFull(flow.GetRequest())
            for i in paramsPost.Keys() {
                keys.Append(str.TrimSpace(i))
            }
        }
        

        if str.Contains(string(req.Header["Content-Type"]), "application/json") {
            _, err = json.New(str.TrimSuffix(
                str.TrimPrefix(
                    string(poc.GetHTTPPacketBody(flow.GetRequest())), 
                    "{", 
                ), 
                "}", 
            ))
            if err != nil {
                return deduplicateStrings(keys)
            }
            

            postBodyJson = json.loads(str.TrimSuffix(
                str.TrimPrefix(
                    string(poc.GetHTTPPacketBody(flow.GetRequest())), 
                    "{", 
                ), 
                "}", 
            ))
            for i in getJsonKey(postBodyJson) {
                keys.Append(str.TrimSpace(i))
            }
        }
    }
    

    return deduplicateStrings(keys)
}

// 构造流量标识符：[METHOD] path?param1,param2,...
buildFlowIdentifier = func(flow) {
    req, err = poc.ParseBytesToHTTPRequest(flow.GetRequest())
    if err != nil {
        return ""
    }
    

    method = flow.Method
    path = req.URL.Path

    paramKeys = parseQueryKeys(flow)
    return "[" + method + "] " + path + "?params=" + str.Join(paramKeys, ",")
}

# 检测是否是Webpack打包文件
isWebpackBundle = func(body) {
    webpackFeatures = ["sourceMappingURL", "webpack_require", "webpack_exports", "webpackJsonp", "# sourceURL=webpack:///", "__webpack_modules__"]

    bodyStr = string(body)

    # 检查是否包含任何webpack特征
    for feature in webpackFeatures {
        if str.Contains(bodyStr, feature) {
            return true
        }
    }
    

    return false
}

# 从webpack文件中提取API路径
extractWebpackAPIs = func(body) {
    bodyStr = string(body)
    extractedAPIs = []

    # API路径提取规则
    apiPatterns = [`['"]/api/[^'"]+['"]`, `['"]/v\d+/[^'"]+['"]`, `['"]/(user|admin|auth|login|register|upload|download)/[^'"]*['"]`, `['"]\/[^'"]*\.(action|do|php|asp|jsp)['"]`, `['"]/graphql['"]`, `['"]ws://[^'"]+['"]`, `['"]wss://[^'"]+['"]`]

    # 使用正则提取API路径
    for pattern in apiPatterns {
        matches = re.FindAll(bodyStr, pattern)
        for match in matches {
            cleanAPI = str.ReplaceAll(match, `"`, "")
            cleanAPI = str.ReplaceAll(cleanAPI, `'`, "")
            println("webpack找到:" + cleanAPI)
            # 添加到全局路径收集器
            globalPaths.Add(cleanAPI)
        }
    }
    

    return extractedAPIs
}

# 检测是否是source map文件
isSourceMapFile = func(path) {
    if path == nil {
        return false
    }
    

    spath := str.ToLower(string(path))
    return re.Match(`\.js\.map([?#].*)?$`, spath)
}

# 处理source map文件
processSourceMapFile = func(url, body) {
    bodyStr = string(body)

    # 检查是否包含sourceRoot等关键字段
    if str.Contains(bodyStr, "sourceRoot") || str.Contains(bodyStr, "sources") {
        sourceMapFiles.Add(url)

        # 尝试解析JSON格式的source map
        _, err = json.New(bodyStr)
        if err == nil {
            sourceMapJson = json.loads(bodyStr)

            # 提取sources字段中的原始文件路径
            if sourceMapJson["sources"] != nil {
                sources = sourceMapJson["sources"]
                if typeof(sources) == typeof([]) {
                    for source in sources {
                        if typeof(source) == string {
                            println("source map找到:" + source)
                            globalPaths.Add(source)
                        }
                    }
                }
            }
            

            if sourceMapJson["sourceRoot"] != nil {
                sourceRoot = sourceMapJson["sourceRoot"]
                if typeof(sourceRoot) == string {
                    println("source map找到:" + sourceRoot)
                    globalPaths.Add(sourceRoot)
                }
            }
        }
        

        return true
    }
    

    return false
}

# 简化后的获取source map函数 - 默认使用HTTPS  
tryGetSourceMap = func(jsUrl) {  
    mapUrl = "https" + jsUrl + ".map"  
    println("请求:" + mapUrl)
    try {  
        map_rsp, _, err = poc.Get(mapUrl, poc.https(true))  # 直接默认使用HTTPS  
        if err == nil && map_rsp != nil {  
            if str.Contains(map_rsp.BareResponse, "sourceRoot") || str.Contains(map_rsp.BareResponse, "sources") {  
                processSourceMapFile(mapUrl, map_rsp.BareResponse)  
                return true  
            }  
        }  
    } catch err {  
        # 静默处理错误  
    }  
      
    return false  
}

# 正则匹配路径
matchReg = func(body) {
    regSlice = []string{`['"` + "`" + `]\/[a-zA-Z0-9_\-\/]+?\.(php|asp|aspx|jsp|json|action|do|html?|htm)(\?[^\s"'` + "`" + `<>]*)?['"` + "`" + `]`, `['"` + "`" + `][a-zA-Z0-9][a-zA-Z0-9_\-\/]*?\.(php|asp|aspx|jsp|json|action|do|html?|htm)(\?[^\s"'` + "`" + `<>]*)?['"` + "`" + `]`, `['"` + "`" + `]\/[a-zA-Z0-9][a-zA-Z0-9_\-/]{1,}['"` + "`" + `]`}
    for _, reg := range regSlice {
        results := re.FindAll(body, reg)
        for _, res := range results {
            res = str.Trim(res, "'\"")
            res = str.TrimSpace(res)
            // 保证以 / 开头
            if !str.HasPrefix(res, "/") {
                res = "/" + res
            }
            

            println("js找到:" + res)
            globalPaths.Add(res)
        }
    }
}

# 检测路径是否是js
isJavaScript = func(path) {
    if path == nil {
        return false
    }
    

    spath := str.ToLower(string(path))
    return re.Match(`\.js([?#].*)?$`, spath)
}

#  检查javascript是否是第三方库
isThirdPartyJS = func(path) {
    if path == nil {
        return false
    }
    

    spath := string(path)
    // 提取文件名：去除路径和 query 参数，转小写
    parts := str.Split(spath, "/")
    last := parts[len(parts) - 1]
    last = str.Split(last, "?")[0]
    fileName := str.ToLower(last)

    patterns := []string{`^jquery([.-]?\d*\.?\d*\.?\d*)?(?:[\.-]cookie)?(?:[\.-]fancybox)?(?:[\.-]validate)?(?:[\.-]artDialog)?(?:[\.-]blockui)?(?:[\.-]pack)?(?:[\.-]base64)?(?:[\.-]md5)?(?:[\.-]min)?\.js$`, `^(?:vue|vue-router|vuex)[.-]?\d*\.?\d*\.?\d*(?:\.min)?\.js$`, `^(react|react-dom)[.-]?\d*\.?\d*\.?\d*(?:\.min)?\.js$`, `^bootstrap(?:\.bundle)?[.-]?\d*\.?\d*\.?\d*(?:[\.-]datepicker|datetimepicker)?(?:[\.-]zh-CN)?(?:[\.-]min)?\.js$`, `^(layui|lay|layer|liger|h-ui|element-ui|ueditor|kindeditor|ant-design)[.-]?\d*\.?\d*\.?\d*(?:[\.-]all)?(?:\.admin)?(?:[\.-]config)?(?:[\.-]min)?\.js$`, `^(echarts|chart|highcharts)[.-]?\d*\.?\d*\.?\d*(?:\.min)?\.js$`, `^(lodash|moment|tableexport|axios|plupload|pqgrid|md5)[.-]?\d*\.?\d*\.?\d*(?:\.full)?(?:\.min)?\.js$`, `^(polyfill|modernizr|device|less|isotope\.pkgd|lhgdialog|kendo\.web|dataTables|editor|seajs-style|seajs-text|tinymce|jsencrypt|backbone|select2|underscore|ext-all|ext-unigui-min|exporter|buttons|v5_float_4)[.-]?\d*\.?\d*\.?\d*(?:[\.-]dev)?(?:[\.-]html5|bootstrap|print|full)?(?:[\.-]min)?\.js$`, `^(datepicker|datetimepicker|wdatepicker|laydate)[.-]?\d*\.?\d*\.?\d*(?:\.min)?\.js$`, `^(?:zh|en|zh-cn|zh-tw|ja|ko)[.-]?\d*\.?\d*\.?\d*(?:\.min)?\.js$`}

    for pat in patterns {
        if re.Match(pat, fileName) {
            return true
        }
    }
    

    return false
}

# 从JSON中提取路径
func extractPathsFromJson(jsn) {
    paths := []
    pathRegex = re.Compile("^/[a-zA-Z0-9/-_.]*$")~
    try {
        for key, value = range jsn {
            if typeof(value) == string {
                if str.HasPrefix(value, "/") && len(value) < 256 && pathRegex.Match(value) {
                    paths = append(paths, value)
                    globalPaths.Add(value)
                    println("JSON找到:" + value)
                }
            }
            

            if typeof(key) == string {
                if str.HasPrefix(key, "/") && len(key) < 256 && pathRegex.Match(key) {
                    paths = append(paths, key)
                    globalPaths.Add(key)
                    println("JSON找到:" + key)
                }
            }
            

            if typeof(value) == typeof(paths) {
                for val in value {
                    if typeof(val) == string {
                        if str.HasPrefix(val, "/") && len(val) < 256 && pathRegex.Match(val) {
                            paths = append(paths, val)
                            globalPaths.Add(val)
                            println("JSON找到:" + val)
                        }
                    }
                    

                    if typeof(val) != string && typeof(val) != int && typeof(val) != float && typeof(val) != bool && val != nil {
                        paths += extractPathsFromJson(val)
                    }
                }
            }
            

            if typeof(value) != string && typeof(value) != int && typeof(value) != float && typeof(value) != bool && value != nil {
                paths += extractPathsFromJson(value)
            }
        }
    } catch err {
        println(err)
    }


    return paths
}
# 主逻辑：处理HTTP流量
yakitFlow = yakit.QueryHTTPFlowsAll()
seen = {}// 用于记录已见过的标识符  
i = 1
j = 1

for flow in yakitFlow {
    req := poc.ParseBytesToHTTPRequest(flow.GetRequest())~
    if isStaticFile(req.URL.Path) {
        i++
        continue
    }
    

    host = req.Host
    if host == "" {
        host = req.Header.Get("Host")
    }
    
    if !isHostAllowed(host) {
        i++
        continue
    }
    
    if flow.FromPlugin != "" && flow.FromPlugin != nil {
        i++
        continue
    }
    

    id = buildFlowIdentifier(flow)
    if id != "" && !seen.Has(codec.Md5(id)) {
        seen.Set(codec.Md5(id), true)
        j++
        req := poc.ParseBytesToHTTPRequest(flow.GetRequest())~
        respBytes := flow.GetResponse()
        if respBytes == nil || len(respBytes) == 0 {
            continue
        }
        

        res = poc.ParseBytesToHTTPResponse(flow.GetResponse())~
        if !isJavaScript(req.URL.Path) {
            globalPaths.Add(req.URL.Path)
        }
        

        if isSourceMapFile(req.URL.Path) {
            body, _ := io.ReadAll(res.Body)
            processSourceMapFile(req.URL.String(), string(body))
            continue
        }
        

        if isJavaScript(req.URL.Path) && !isThirdPartyJS(req.URL.Path) {
            body, _ := io.ReadAll(res.Body)
            bodyStr = string(body)

            # 检测是否为webpack文件并提取API
            if isWebpackBundle(bodyStr) {
                webpackFiles.Add(req.URL.Path)
                extractWebpackAPIs(bodyStr)

                # 尝试获取对应的source map文件
                 # 简化调用，直接传入URL字符串  
                tryGetSourceMap(req.URL.String())  
            } else {
                matchReg(bodyStr)
            }
        }
        

        if str.Contains(string(res.Header["Content-Type"]), "application/json") {
            body, _ := io.ReadAll(res.Body)
            _, err = json.New(body)
            if err != nil {
                continue
            }
            

            postBodyJson = json.loads(body)
            extractPathsFromJson(postBodyJson)
        }
    }
    

    i++
}
//输出结果函数
//输出结果函数  
output = func(str_name, container_result) {  
    yakit.EnableText(str_name)  
    output_str = ""  
      
    # 检查是否是Set容器还是普通数组  
    if typeof(container_result.Each) == "function" {  
        # 如果是Set容器，使用Each方法  
        container_result.Each(func(i) {  
            if str.IsAllVisibleASCII(i) {  
                output_str += i + "\n"  
            }  
        })  
    } else {  
        # 如果是普通数组，使用for循环  
        for item in container_result {  
            if str.IsAllVisibleASCII(item) {  
                output_str += item + "\n"  
            }  
        }  
    }  
      
    yakit.TextTabData(str_name, output_str)  
    yakit.Text(output_str)  
}

println("=== 流量分析统计 ===")
println("总流量数:", i)
println("去重后流量数:", j)
println("唯一标识符数:", seen.Len())

# 输出三个主要部分的结果
println("\n=== 1. 提取到的所有路径 (去重排序) ===")
allPaths = globalPaths.ToSlice().StringSlice()
allPaths.Sort()
for path in allPaths {
    println("路径:", path)
}

println("总路径数:", len(allPaths))

println("\n=== 2. 发现的Webpack打包文件 ===")
webpackList = webpackFiles.ToSlice().StringSlice()
webpackList.Sort()
for webpack in webpackList {
    println("Webpack文件:", webpack)
}


println("Webpack文件数:", len(webpackList))

println("\n=== 3. 发现的Source Map文件 ===")
sourceMapList = sourceMapFiles.ToSlice().StringSlice()
sourceMapList.Sort()
for sourceMap in sourceMapList {
    println("Source Map文件:", sourceMap)
}


println("Source Map文件数:", len(sourceMapList))

println("\n=== 分析完成 ===")

# 路径模式归纳函数  
normalizePathPattern = func(path) {  
    pattern = path  
    // 严格匹配32位UUID
    pattern = re.ReplaceAll(pattern, `\b[a-f0-9]{32}\b`, "{{randstr(32)}}")
    // 严格匹配6位及以上数字ID
    pattern = re.ReplaceAll(pattern, `\b\d{6,}\b`, "{{randint(0,100)}}")
    # 3. 清理和规范化路径  
    # 去除尾部斜杠  
    pattern = str.TrimSuffix(pattern, "/")  
    # 合并重复斜杠  
    pattern = re.ReplaceAll(pattern, `//+`, "/")  
      
    return pattern  
}
# 遍历globalPaths并生成模式  
globalPaths.Each(func(path) {  
    pattern = normalizePathPattern(path)  
    patternPaths.Add(pattern)  
}) 

output("Source Map文件", sourceMapFiles)
output("Webpack文件", webpackFiles)
output("原始路径", globalPaths)
output("路径归纳模式", patternPaths)
